//! Codex theme: color tokens, metrics, embedded icons and fonts.
//!
//! Colors live in `tokens.rs`, generated by `tools/extract/theme.py` from the original
//! renderer CSS plus the inline `:root` vars the app's JS computes (`theme_vars.mjs`).
//! Each field's doc comment is the CSS value the original paints, so a `spec.json` style
//! maps to a field by its CSS variable.
//!
//! Fonts: the UI text is the system font (`.SystemUIFont`, SF Pro). `assets/fonts` holds
//! the bundled faces, registered by [`load_fonts`]:
//! - "OpenAI Sans" 400/500/600: `.font-openai-sans` (`--font-openai-sans`), used for the
//!   sidebar header `h1` title, the Codex/ChatGPT mode switch labels, and onboarding and
//!   standalone route pages and dialogs.
//! - "OpenAI Serif" 300: `._openAISerif` in the control panel (serif display and KaTeX).

mod tokens;

pub use tokens::{Appearance, Theme};

use gpui::{App, AssetSource, FontWeight, Global, Pixels, SharedString, px};
use std::borrow::Cow;

impl Global for Theme {}

pub trait ActiveTheme {
    fn theme(&self) -> &Theme;
}

impl ActiveTheme for App {
    fn theme(&self) -> &Theme {
        self.global::<Theme>()
    }
}

/// Font size and line height of one type scale step.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct TextSize {
    pub size: Pixels,
    pub line_height: Pixels,
}

const fn text(size: f32, line_height: f32) -> TextSize {
    TextSize {
        size: px(size),
        line_height: px(line_height),
    }
}

