/// Serves `assets/` (icons/*.svg, fonts/*.ttf), embedded in the binary.
#[derive(rust_embed::RustEmbed)]
#[folder = "../../assets"]
pub struct Assets;

impl AssetSource for Assets {
    fn load(&self, path: &str) -> anyhow::Result<Option<Cow<'static, [u8]>>> {
        Ok(Self::get(path).map(|file| file.data))
    }

    fn list(&self, path: &str) -> anyhow::Result<Vec<SharedString>> {
        Ok(Self::iter()
            .filter(|p| p.starts_with(path))
            .map(SharedString::from)
            .collect())
    }
}

/// Registers the bundled OpenAI Sans / Serif faces with the text system.
pub fn load_fonts(cx: &mut App) {
    let fonts = Assets::iter()
        .filter(|p| p.starts_with("fonts/"))
        .filter_map(|p| Assets::get(&p))
        .map(|file| file.data)
        .collect();
    cx.text_system()
        .add_fonts(fonts)
        .expect("bundled fonts are valid TTF");
}

#[cfg(test)]
mod tests {
    use super::*;
    use gpui::{Hsla, Rgba};

    fn bytes(color: Hsla) -> [u8; 4] {
        let c = Rgba::from(color);
        [c.r, c.g, c.b, c.a].map(|v| (v * 255.).round() as u8)
    }

    /// Computed styles from refs/home/dark@1280x832.spec.json and
    /// refs/settings/light@1280x832.spec.json, as Chromium paints them.
    #[test]
    fn reproduces_reference_colors() {
        let dark = Theme::dark();
        // `main._MainContentSurface` backgroundColor rgb(24, 24, 24)
        assert_eq!(bytes(dark.surface), [24, 24, 24, 255]);
        // `.sidebar-navigation` oklab(0.209035 0.00000952929 0.00000418723 / 0.65)
        assert_eq!(bytes(dark.sidebar_background), [24, 24, 24, 166]);
        // body color rgb(255, 255, 255)
        assert_eq!(bytes(dark.text), [255, 255, 255, 255]);
        // nav row text oklab(0.999994 0.0000455678 0.0000200868 / 0.85)
        assert_eq!(bytes(dark.text_default_nav), [255, 255, 255, 217]);
        // `_PageSurfaceLayout` color(srgb 0.156863 0.156863 0.156863 / 0.8)
        assert_eq!(bytes(dark.page_surface_layout), [40, 40, 40, 204]);

        let light = Theme::light();
        // body color rgb(26, 28, 31)
        assert_eq!(bytes(light.text), [26, 28, 31, 255]);
        // `_PageSurfaceLayout` color(srgb 0.964706 0.964706 0.964706 / 0.85)
        assert_eq!(bytes(light.page_surface_layout), [246, 246, 246, 217]);
        // muted labels rgba(26, 28, 31, 0.494)
        assert_eq!(bytes(light.text_tertiary), [26, 28, 31, 126]);
    }

    #[test]
    fn serves_icons_and_fonts() {
        assert!(Assets.load("icons/home.svg").unwrap().is_some());
        assert_eq!(Assets.list("fonts/").unwrap().len(), 4);
    }
}
